def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Locate the solid reference line.
    line = None
    for r in range(h):
        if grid[r][0] != background and all(v == grid[r][0] for v in grid[r]):
            line = ("h", r, grid[r][0])
            break
    if line is None:
        for c in range(w):
            if grid[0][c] != background and all(grid[r][c] == grid[0][c] for r in range(h)):
                line = ("v", c, grid[0][c])
                break
    if line is None:
        return [row[:] for row in grid]

    axis, line_pos, line_color = line
    obj = [(r, c, grid[r][c])
           for r in range(h) for c in range(w)
           if grid[r][c] != background and grid[r][c] != line_color]
    if not obj:
        return [row[:] for row in grid]

    positions = [r if axis == "h" else c for r, c, _ in obj]
    low, high = min(positions), max(positions)

    # Slide the object toward the reference line until adjacent.
    if high < line_pos:
        shift = line_pos - 1 - high
    else:
        shift = line_pos + 1 - low

    out = [row[:] for row in grid]
    for r, c, _ in obj:
        out[r][c] = background

    moved_positions = []
    for r, c, color in obj:
        if axis == "h":
            r += shift
            if 0 <= r < h:
                out[r][c] = color
                moved_positions.append(r)
        else:
            c += shift
            if 0 <= c < w:
                out[r][c] = color
                moved_positions.append(c)

    if moved_positions:
        if max(positions) < line_pos:
            stripe = min(moved_positions) - 1
        else:
            stripe = max(moved_positions) + 1

        if axis == "h" and 0 <= stripe < h:
            out[stripe] = [8] * w
        elif axis == "v" and 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
